---@type IDataInfo
local IDataInfo = Plugins.Require("data_info", isClient and "client.info.CDataInfo" or "server.info.SDataInfo")
---@class SafeLockInfo : IDataInfo
local SafeLockInfo = class("SafeLockInfo", IDataInfo)
---@type CSafeLockPkSender | SSafeLockPkSender
local SafeLockPkSender = T(Global, "PidPacketSender")
---@type ReportEvent
local ReportEvent = T(Global, "ReportEvent")

local function checkPasswordValid(password)
    if #password < 6 or #password > 12 then
        return false
    end
    return tonumber(password) ~= nil
end

function SafeLockInfo:onCreate()
    ---key, defValue, toSelf, toOther, saveDB
    self:initKey(Define.SafeLockInfoKey.Password, "", false, false, true)
    self:initKey(Define.SafeLockInfoKey.HasPassword, false, true, false, true)
    self:initKey(Define.SafeLockInfoKey.Locked, true, true, false, false)
    self:initKey(Define.SafeLockInfoKey.ForceUnlockTime, 0, true, false, true)
    self:initKey(Define.SafeLockInfoKey.UnlockPsdTime, 0, false, false, true)
    self:initKey(Define.SafeLockInfoKey.WrongTimes, 0, true, false, true)
    self:initKey(Define.SafeLockInfoKey.WaitEndTime, 0, true, false, true)
    self:initKey(Define.SafeLockInfoKey.LockOpen, false, true, false, true)
end

function SafeLockInfo:hasPassword()
    local hasPassword = self:getValue(Define.SafeLockInfoKey.HasPassword)
    if not hasPassword then
        return false
    end
    ---有密码
    local forceTime = self:getValue(Define.SafeLockInfoKey.ForceUnlockTime)
    if forceTime == 0 or forceTime > os.time() then
        ---没有强制解锁或强制解锁时间未到，则有密码
        return true
    end
    ---强制解锁时间到了，无密码
    return false
end

---@param force boolean 强制检查，用于设置安全锁开关
function SafeLockInfo:isLocked(force)
    if force then
        return self:getValue(Define.SafeLockInfoKey.Locked)
    else
        if self:getValue(Define.SafeLockInfoKey.LockOpen) then
            return self:getValue(Define.SafeLockInfoKey.Locked)
        else
            return false
        end
    end
end

