function SafeLockInfo:showUnlockTipDialog()
    if CustomDialog.isShow() then
        LuaTimer:scheduleTicker(function()
            self:showUnlockTipDialog()
        end, 1, 1)
        return
    end
    CustomDialog.builder()
                .setTitleText("unlock.safe.lock.title")
                .setLeftButtonImage("set:new_button.json image:btn_common_blue")
                .setHideListener(function()
        CustomDialog.setLeftButtonImage("set:new_button.json image:btn_common_red")
    end)
    local tip
    if self:hasPassword() then
        if self:isLocked(true) then
            tip = "check.safe.lock.unlocked1"
            CustomDialog.setLeftText("unlock.safe.lock.update")
                        .setLeftClickListener(function()
                ---修改密码
                showUpdatePasswordDialog()
                return true
            end)
                        .setRightText("unlock.safe.lock.title")
                        .setRightClickListener(function()
                self:showUnlockDialog()
                return true
            end)
        else
            tip = "check.safe.lock.unlocked2"
            ---修改密码
            CustomDialog.setRightText("unlock.safe.lock.update")
                        .setRightClickListener(function()
                showUpdatePasswordDialog()
                return true
            end)
        end
    else
        tip = "check.safe.lock.unlocked3"
        CustomDialog.setRightText("set.safe.lock.title")
                    .setRightClickListener(function()
            showSetPasswordDialog()
            return true
        end)
    end
    SwitchTipContent:showTip(tip, "set.safe.lock.switch",
            self:getValue(Define.SafeLockInfoKey.LockOpen),
            function(switch)
                if SafeLockPkSender:trySwitchSafeLockOpen(switch) then
                    self:setValue(Define.SafeLockInfoKey.LockOpen, switch)
                    CustomDialog.hide()
                    CustomDialog.builder()
                                .setContentText(Lang:getString(switch and "set.safe.lock.switch.tip1" or "set.safe.lock.switch.tip2"))
                                .setHideLeftButton()
                                .setHideListener(function()
                        LuaTimer:scheduleTicker(function()
                            self:showUnlockTipDialog()
                        end, 1, 1)
                    end)        .show()
                    return true
                else
                    if self:hasPassword() then
                        self:showUnlockDialog()
                    else
                        showSetPasswordDialog()
                    end
                    return true
                end
            end)
    CustomDialog.setContentView(SwitchTipContent)
                .show()
end

---@param force boolean 强制检查，用于设置安全锁开关
function SafeLockInfo:checkUnlock(force)
    if not self:isLocked(force) then
        return true
    end
    if isServer then
        SafeLockPkSender:tryCheckSafeLock(self.player)
    else
        self:showUnlockTipDialog()
    end
    return false
end

function SafeLockInfo:trySetPassword(password)
    if self:hasPassword() then
        ---已经设置过密码了
        return
    end
    if not checkPasswordValid(password) then
        return
    end
    self:setValue(Define.SafeLockInfoKey.Password, password)
    self:setValue(Define.SafeLockInfoKey.HasPassword, true)
    ---设置密码，首次设置默认解锁
    self:setValue(Define.SafeLockInfoKey.Locked, false)
    self:setValue(Define.SafeLockInfoKey.ForceUnlockTime, 0)
    self:setValue(Define.SafeLockInfoKey.WaitEndTime, 0)
    self:setValue(Define.SafeLockInfoKey.WrongTimes, 0)
    self:setValue(Define.SafeLockInfoKey.UnlockPsdTime, 0)
    SafeLockPkSender:sendShowToast(self.player.rakssid, "set.safe.lock.success")
    ReportEvent.reportEvent(self.player.userId, "safe_lock_operate", nil, { source = "SetPassword" })
end

function SafeLockInfo:checkWaitEndTime()
    local maxWaitTime = 3600 ---最多一小时
    if self:getValue(Define.SafeLockInfoKey.UnlockPsdTime) < os.time() - maxWaitTime then
        ---1小时后恢复正常
        self:setValue(Define.SafeLockInfoKey.WrongTimes, 0)
        self:setValue(Define.SafeLockInfoKey.WaitEndTime, 0)
    end
    if self:getValue(Define.SafeLockInfoKey.WaitEndTime) > os.time() then
        ---时间未到，不做解锁校验
        return false
    end
    ---更新校验时间
    self:setValue(Define.SafeLockInfoKey.UnlockPsdTime, os.time())
    return true
end

---密码错误
function SafeLockInfo:onCheckPsdWrong()
    self:incValue(Define.SafeLockInfoKey.WrongTimes, 1)
    local maxWaitTime = 3600 ---最多一小时
    local waitSecond = math.max(0, self:getValue(Define.SafeLockInfoKey.WrongTimes) - 4) * 300
    waitSecond = math.min(waitSecond, maxWaitTime)
    if waitSecond > 0 then
        self:setValue(Define.SafeLockInfoKey.WaitEndTime, os.time() + waitSecond)
    end
end

function SafeLockInfo:tryUnlockPassword(password)
    if not self:hasPassword() then
        ---未设置密码
        return false
    end
    if not self:checkWaitEndTime() then
        return
    end
    if password ~= self:getValue(Define.SafeLockInfoKey.Password) then
        SafeLockPkSender:sendShowToast(self.player.rakssid, "unlock.safe.lock.tip1")
        self:onCheckPsdWrong()
        return false
    end
    self:setValue(Define.SafeLockInfoKey.WrongTimes, 0)
    self:setValue(Define.SafeLockInfoKey.Locked, false)
    self:setValue(Define.SafeLockInfoKey.ForceUnlockTime, 0)
    SafeLockPkSender:sendShowToast(self.player.rakssid, "unlock.safe.lock.success")
    ReportEvent.reportEvent(self.player.userId, "safe_lock_operate", nil, { source = "UnlockPassword" })
    return true
end

function SafeLockInfo:tryUpdatePassword(oldPsd, newPsd)
    if not self:hasPassword() then
        ---未设置密码
        return
    end
    if not self:checkWaitEndTime() then
        return
    end
    if oldPsd ~= self:getValue(Define.SafeLockInfoKey.Password) then
        SafeLockPkSender:sendShowToast(self.player.rakssid, "unlock.safe.lock.tip1")
        self:onCheckPsdWrong()
        return
    end
    if not checkPasswordValid(newPsd) then
        return
    end
    self:setValue(Define.SafeLockInfoKey.Password, newPsd)
    self:setValue(Define.SafeLockInfoKey.ForceUnlockTime, 0)
    SafeLockPkSender:sendShowToast(self.player.rakssid, "set.safe.lock.success")
    ReportEvent.reportEvent(self.player.userId, "safe_lock_operate", nil, { source = "UpdatePassword" })
end

function SafeLockInfo:tryStartForceUnlock()
    if not self:hasPassword() then
        ---未设置密码
        return
    end
    local forceTime = self:getValue(Define.SafeLockInfoKey.ForceUnlockTime)
    if forceTime > os.time() then
        ---正在强制解锁中...
        return
    end
    local endTime = os.time() + DateUtil.getWeekSeconds()
    self:setValue(Define.SafeLockInfoKey.ForceUnlockTime, endTime)
    SafeLockPkSender:sendShowToast(self.player.rakssid, "set.safe.lock.success")
    ReportEvent.reportEvent(self.player.userId, "safe_lock_operate", nil, { source = "ForceUnlock" })
end

return SafeLockInfo